/** Prefer a car that is already coming your way — the sweep is what makes
 *  the system feel fair without any explicit fairness accounting. */
final class LookDispatcher implements Dispatcher {

    @Override
    public ElevatorCar select(List<ElevatorCar> cars, HallCall call) {
        return cars.stream()
            .min(Comparator.comparingInt(car -> cost(car, call)))
            .orElseThrow();
    }

    private int cost(ElevatorCar car, HallCall call) {
        int distance = Math.abs(car.currentFloor() - call.floor());

        // Already sweeping toward the call, in the call's direction: cheapest.
        if (car.direction() == call.direction() && movingToward(car, call)) {
            return distance;
        }
        // Idle: cheap, but slightly worse than a car already on its way.
        if (car.direction() == Direction.NONE) {
            return distance + PENALTY_IDLE;
        }
        // Moving the wrong way: it must finish its sweep first, so the real
        // cost is the rest of its run plus the trip back.
        return distance + PENALTY_WRONG_WAY + car.stopsAhead().size();
    }

    private boolean movingToward(ElevatorCar car, HallCall call) {
        return car.direction() == Direction.UP
            ? call.floor() >= car.currentFloor()
            : call.floor() <= car.currentFloor();
    }
}

/** Stops are a sorted set, not a queue. Sorted gives "next stop in this
 *  direction" in O(log n); a set makes a duplicate press a no-op, which is
 *  exactly what a real button does. */
private final TreeSet<Integer> stopsAhead = new TreeSet<>();

void step() {
    if (stopsAhead.isEmpty()) { direction = Direction.NONE; return; }

    Integer next = direction == Direction.DOWN
        ? stopsAhead.floor(currentFloor)      // nearest stop at or below
        : stopsAhead.ceiling(currentFloor);   // nearest stop at or above

    if (next == null) {                       // nothing ahead — reverse (LOOK)
        direction = direction == Direction.UP ? Direction.DOWN : Direction.UP;
        return;
    }
    if (next == currentFloor) { openDoors(); stopsAhead.remove(next); return; }
    currentFloor += direction == Direction.UP ? 1 : -1;
}
